-- FAQ per festival. Only 'published' entries reach visitors and the FAQ bot.
CREATE TABLE faqs (
  festival_id TEXT NOT NULL REFERENCES festivals(id) ON DELETE CASCADE,
  id TEXT NOT NULL,
  question TEXT NOT NULL,
  answer TEXT NOT NULL,
  category TEXT NOT NULL DEFAULT 'Allgemein',
  keywords TEXT NOT NULL DEFAULT '',
  source TEXT,              -- where the answer comes from (e.g. "Hausordnung"), shown with every bot answer
  status TEXT NOT NULL DEFAULT 'draft' CHECK (status IN ('draft', 'published')),
  sort INTEGER NOT NULL DEFAULT 0,
  updated_at INTEGER NOT NULL, -- shown as "Stand"
  PRIMARY KEY (festival_id, id)
);

-- Demo FAQ for the demo festival (generated by scripts/build-faq-seed.mts).
INSERT INTO faqs (festival_id, id, question, answer, category, keywords, source, status, sort, updated_at) VALUES ('realm', 'einlass-zeiten', 'Wann öffnet der Einlass?', 'Der Einlass öffnet Donnerstag um 10:00 Uhr. Freitag und Samstag ist das Gelände ab 12:00 Uhr geöffnet, der Campingplatz durchgehend.', 'Einlass', 'einlass öffnungszeiten tore', 'Infoseite Anreise', 'published', 0, 1811808000000);
INSERT INTO faqs (festival_id, id, question, answer, category, keywords, source, status, sort, updated_at) VALUES ('realm', 'baendchen', 'Wo bekomme ich mein Bändchen?', 'Tickets werden am Eingang Nord gegen ein Bändchen getauscht. Bitte Ticket (digital oder ausgedruckt) und Ausweis bereithalten.', 'Tickets', 'bändchen ticket umtausch wristband', 'Ticket-AGB', 'published', 1, 1811808000000);
INSERT INTO faqs (festival_id, id, question, answer, category, keywords, source, status, sort, updated_at) VALUES ('realm', 'bändchen-verloren', 'Ich habe mein Bändchen verloren – was nun?', 'Komm mit Ausweis und Ticket-Nummer zum Info-Zelt. Gerissene Bändchen werden ersetzt, verlorene nur mit Nachweis.', 'Tickets', 'bändchen verloren kaputt gerissen', 'Ticket-AGB', 'published', 2, 1811808000000);
INSERT INTO faqs (festival_id, id, question, answer, category, keywords, source, status, sort, updated_at) VALUES ('realm', 'camping', 'Darf ich einen Pavillon mitbringen?', 'Pavillons bis 3 × 3 m sind erlaubt. Gaskocher nur mit Kartusche, offene Feuer und Holzkohlegrills sind verboten.', 'Camping', 'camping zelt pavillon gaskocher grill', 'Campingregeln', 'published', 3, 1811808000000);
INSERT INTO faqs (festival_id, id, question, answer, category, keywords, source, status, sort, updated_at) VALUES ('realm', 'mitnehmen', 'Was darf ich aufs Gelände mitnehmen?', 'Erlaubt sind leere Plastikflaschen bis 1,5 l, kleine Taschen und Sonnencreme. Glas, Dosen und Getränke von außen sind auf dem Konzertgelände verboten.', 'Gelände', 'erlaubt verboten flaschen glas taschen', 'Hausordnung', 'published', 4, 1811808000000);
INSERT INTO faqs (festival_id, id, question, answer, category, keywords, source, status, sort, updated_at) VALUES ('realm', 'wasser', 'Gibt es kostenloses Trinkwasser?', 'Ja, an drei Wasserstellen (Nord, Lagoon, Forest) kannst du kostenlos auffüllen. Die Karte zeigt sie unter „Wasser“.', 'Gelände', 'wasser trinkwasser auffüllen', 'Geländeplan', 'published', 5, 1811808000000);
INSERT INTO faqs (festival_id, id, question, answer, category, keywords, source, status, sort, updated_at) VALUES ('realm', 'essen', 'Gibt es veganes Essen?', 'Ja, im Food Court gibt es an jedem Stand mindestens ein veganes Gericht.', 'Essen', 'essen vegan vegetarisch food court', 'Gastro-Übersicht', 'published', 6, 1811808000000);
INSERT INTO faqs (festival_id, id, question, answer, category, keywords, source, status, sort, updated_at) VALUES ('realm', 'bezahlen', 'Kann ich mit Karte zahlen?', 'Alle Stände nehmen Karte und Handy. Bargeld wird nur am Info-Zelt angenommen.', 'Essen', 'bezahlen karte bargeld cashless', 'Gastro-Übersicht', 'published', 7, 1811808000000);
INSERT INTO faqs (festival_id, id, question, answer, category, keywords, source, status, sort, updated_at) VALUES ('realm', 'akku', 'Wo kann ich mein Handy laden?', 'Am Info-Zelt gibt es Ladestationen und Powerbanks zum Ausleihen (5 € Pfand).', 'Service', 'handy akku laden strom powerbank', 'Service-Seite', 'published', 8, 1811808000000);
INSERT INTO faqs (festival_id, id, question, answer, category, keywords, source, status, sort, updated_at) VALUES ('realm', 'fundsachen', 'Wo ist das Fundbüro?', 'Fundsachen werden im Info-Zelt gesammelt, nach dem Festival noch bis Montag 14 Uhr.', 'Service', 'fundsachen verloren lost found', 'Service-Seite', 'published', 9, 1811808000000);
INSERT INTO faqs (festival_id, id, question, answer, category, keywords, source, status, sort, updated_at) VALUES ('realm', 'hilfe', 'Wo finde ich Hilfe, wenn es mir nicht gut geht?', 'Das Sanitätszelt ist rund um die Uhr besetzt. Das Awareness-Team erreichst du am Info-Zelt. Im Notfall: 112.', 'Sicherheit', 'sanitäter hilfe awareness notfall', 'Sicherheitskonzept', 'published', 10, 1811808000000);
INSERT INTO faqs (festival_id, id, question, answer, category, keywords, source, status, sort, updated_at) VALUES ('realm', 'anreise', 'Wie komme ich ohne Auto hin?', 'Vom Bahnhof fährt ein Shuttle alle 15 Minuten (am Anreisetag alle 10), im Ticket enthalten.', 'Anreise', 'anreise shuttle bahn bus zug', 'Infoseite Anreise', 'published', 11, 1811808000000);
